import * as React from "react";
import { cn } from "@/registry/lib/utils";

/*
 * Alert: an inline message that stays on the page until it's resolved or
 * dismissed, like a failed sync or an expiring plan. For a passing message use
 * a snackbar or toast; to interrupt the user, an alert dialog.
 *
 * Errors and warnings are announced immediately (role="alert"); other types
 * politely (role="status"). Render it when the condition appears, so the
 * announcement happens then.
 */

export type AlertType = "info" | "success" | "warning" | "error";

const colors: Record<AlertType, string> = {
  info: "bg-secondary-container text-on-secondary-container",
  success: "bg-primary-container text-on-primary-container",
  warning: "bg-tertiary-container text-on-tertiary-container",
  error: "bg-error-container text-on-error-container",
};

const icons: Record<AlertType, string> = {
  info: "M11 17h2v-6h-2Zm1-8q.43 0 .71-.29Q13 8.43 13 8t-.29-.71Q12.43 7 12 7t-.71.29Q11 7.57 11 8t.29.71Q11.57 9 12 9Zm0 13q-2.08 0-3.9-.79-1.82-.79-3.17-2.14-1.35-1.35-2.14-3.17Q2 14.08 2 12t.79-3.9q.79-1.82 2.14-3.17Q6.28 3.58 8.1 2.79 9.92 2 12 2t3.9.79q1.82.79 3.17 2.14 1.35 1.35 2.14 3.17Q22 9.92 22 12t-.79 3.9q-.79 1.82-2.14 3.17-1.35 1.35-3.17 2.14Q14.08 22 12 22Z",
  success: "m10.6 16.6 7.05-7.05-1.4-1.4-5.65 5.65-2.85-2.85-1.4 1.4ZM12 22q-2.08 0-3.9-.79-1.82-.79-3.17-2.14-1.35-1.35-2.14-3.17Q2 14.08 2 12t.79-3.9q.79-1.82 2.14-3.17Q6.28 3.58 8.1 2.79 9.92 2 12 2t3.9.79q1.82.79 3.17 2.14 1.35 1.35 2.14 3.17Q22 9.92 22 12t-.79 3.9q-.79 1.82-2.14 3.17-1.35 1.35-3.17 2.14Q14.08 22 12 22Z",
  warning: "M1 21 12 2l11 19Zm11-3q.43 0 .71-.29Q13 17.43 13 17t-.29-.71Q12.43 16 12 16t-.71.29Q11 16.57 11 17t.29.71Q11.57 18 12 18Zm-1-3h2v-5h-2Z",
  error: "M12 17q.43 0 .71-.29Q13 16.43 13 16t-.29-.71Q12.43 15 12 15t-.71.29Q11 15.57 11 16t.29.71Q11.57 17 12 17Zm-1-4h2V7h-2Zm1 9q-2.08 0-3.9-.79-1.82-.79-3.17-2.14-1.35-1.35-2.14-3.17Q2 14.08 2 12t.79-3.9q.79-1.82 2.14-3.17Q6.28 3.58 8.1 2.79 9.92 2 12 2t3.9.79q1.82.79 3.17 2.14 1.35 1.35 2.14 3.17Q22 9.92 22 12t-.79 3.9q-.79 1.82-2.14 3.17-1.35 1.35-3.17 2.14Q14.08 22 12 22Z",
};

export interface AlertProps extends Omit<React.ComponentProps<"div">, "title"> {
  type?: AlertType;
  title?: React.ReactNode;
  /** Replaces the type's icon; pass `null` for no icon. */
  icon?: React.ReactNode;
  /** Buttons under the text, e.g. `<Button variant="text" size="sm">Retry</Button>`. */
  actions?: React.ReactNode;
  /** Shows a close button that calls this. */
  onDismiss?: () => void;
  /** Accessible name of the close button. */
  dismissLabel?: string;
}

export function Alert({ className, type = "info", title, icon, actions, onDismiss, dismissLabel = "Dismiss", children, role, ...props }: AlertProps) {
  const urgent = type === "error" || type === "warning";
  return (
    <div
      data-slot="alert"
      data-type={type}
      role={role ?? (urgent ? "alert" : "status")}
      className={cn("flex items-start gap-3 rounded-shape-large p-4", colors[type], className)}
      {...props}
    >
      {icon !== null && (
        <span aria-hidden="true" className="flex shrink-0 pt-0.5 [&_svg]:size-5">
          {icon ?? (
            <svg viewBox="0 0 24 24" fill="currentColor">
              <path d={icons[type]} />
            </svg>
          )}
        </span>
      )}
      <div className="flex min-w-0 flex-1 flex-col gap-1">
        {title && <div className="text-title-small">{title}</div>}
        {children && <div className="text-body-medium opacity-90">{children}</div>}
        {/* Text buttons inside pick up the alert's content color. */}
        {actions && <div className="-ms-3 mt-1 flex flex-wrap gap-2 [&_[data-slot=button]]:text-current">{actions}</div>}
      </div>
      {onDismiss && (
        <button
          type="button"
          aria-label={dismissLabel}
          onClick={onDismiss}
          className="state-layer focus-ring -my-2 -me-2 flex size-10 shrink-0 cursor-pointer items-center justify-center rounded-shape-full"
        >
          <svg viewBox="0 0 24 24" aria-hidden="true" fill="currentColor" className="size-5">
            <path d="M6.4 19 5 17.6l5.6-5.6L5 6.4 6.4 5l5.6 5.6L17.6 5 19 6.4 13.4 12l5.6 5.6-1.4 1.4-5.6-5.6Z" />
          </svg>
        </button>
      )}
    </div>
  );
}
